BEGIN;DO $preflight$ DECLARE e jsonb;BEGIN e:=nullif(current_setting('tus.human_reward_catalog_authority',true),'')::jsonb;IF current_user<>'postgres' OR e IS NULL OR e->>'schema_version' IS DISTINCT FROM 'human-reward-catalog-authority/1' OR e->>'review' IS DISTINCT FROM '0/0/0' OR coalesce((e->>'expires_at')::timestamptz,'-infinity'::timestamptz)<=clock_timestamp() THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_AUTHORITY';END IF;IF md5(pg_get_functiondef('public.mission_factory_catalog_v1()'::regprocedure)) IS DISTINCT FROM '68ea3238f8c22024cf5ad0f67bc2390b' OR (SELECT proacl::text FROM pg_proc WHERE oid='public.mission_factory_catalog_v1()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres}' OR (SELECT proowner::regrole::text FROM pg_proc WHERE oid='public.mission_factory_catalog_v1()'::regprocedure) IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_BASELINE_DRIFT';END IF;IF md5(pg_get_functiondef('public.mission_factory_quest_reward_catalog_v2()'::regprocedure)) IS DISTINCT FROM 'aa3579cf022a89f47c0c451aa596c6c8' OR (SELECT proacl::text FROM pg_proc WHERE oid='public.mission_factory_quest_reward_catalog_v2()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres}' OR (SELECT proowner::regrole::text FROM pg_proc WHERE oid='public.mission_factory_quest_reward_catalog_v2()'::regprocedure) IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_BASELINE_DRIFT';END IF;IF md5(pg_get_functiondef('mission_factory_owner.c408_stage1_complete_assert_v1()'::regprocedure)) IS DISTINCT FROM '55dbabd6908714530a59299559d7954c' OR (SELECT proacl::text FROM pg_proc WHERE oid='mission_factory_owner.c408_stage1_complete_assert_v1()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' OR (SELECT proowner::regrole::text FROM pg_proc WHERE oid='mission_factory_owner.c408_stage1_complete_assert_v1()'::regprocedure) IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_BASELINE_DRIFT';END IF;IF md5(pg_get_functiondef('mission_factory_owner.c444_runtime_ports_complete_assert_v1()'::regprocedure)) IS DISTINCT FROM '4fdc7cc83f51e9e7156b0552e40c3c2c' OR (SELECT proacl::text FROM pg_proc WHERE oid='mission_factory_owner.c444_runtime_ports_complete_assert_v1()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' OR (SELECT proowner::regrole::text FROM pg_proc WHERE oid='mission_factory_owner.c444_runtime_ports_complete_assert_v1()'::regprocedure) IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_BASELINE_DRIFT';END IF;IF md5(pg_get_functiondef('public.mission_factory_catalog_v2()'::regprocedure)) IS DISTINCT FROM '3e59df494864381f59a9a6ef47671aaf' OR (SELECT proacl::text FROM pg_proc WHERE oid='public.mission_factory_catalog_v2()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' OR (SELECT proowner::regrole::text FROM pg_proc WHERE oid='public.mission_factory_catalog_v2()'::regprocedure) IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_BASELINE_DRIFT';END IF;IF md5(pg_get_functiondef('public.mission_factory_catalog_v4()'::regprocedure)) IS DISTINCT FROM '7900289e36fbb7cbcea15c27cd3d9e55' OR (SELECT proacl::text FROM pg_proc WHERE oid='public.mission_factory_catalog_v4()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres}' OR (SELECT proowner::regrole::text FROM pg_proc WHERE oid='public.mission_factory_catalog_v4()'::regprocedure) IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_BASELINE_DRIFT';END IF;IF md5(pg_get_functiondef('public.is_staff()'::regprocedure)) IS DISTINCT FROM 'da3d2441d69193629f7ee3d795bb1c3a' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_SCOPE_DRIFT';END IF;IF md5(pg_get_functiondef('mission_factory_owner.quest_fixed30_admission_assert_v2()'::regprocedure)) IS DISTINCT FROM '98c3ff13d0672129e0f200871c95a848' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_SCOPE_DRIFT';END IF;IF md5(pg_get_functiondef('mission_factory_owner.c416_kind_live_v1()'::regprocedure)) IS DISTINCT FROM 'ca836584b84f114ede05277e91610235' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_SCOPE_DRIFT';END IF;IF md5(pg_get_functiondef('mission_factory_owner.c444_enabled_v1()'::regprocedure)) IS DISTINCT FROM '2b8d0af96cf3601f48bbfe9f862c9823' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_SCOPE_DRIFT';END IF;IF md5(pg_get_functiondef('png_builder_internal.npc_media_completion_staff_v1(uuid)'::regprocedure)) IS DISTINCT FROM 'c1fa73e741924f28fd1ed80273e9fe32' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_SCOPE_DRIFT';END IF;IF md5(pg_get_functiondef('mission_factory_owner.manual_authoring_assert_v1(text,uuid)'::regprocedure)) IS DISTINCT FROM 'a19a159cdf5a1f7776699f042376be41' THEN RAISE EXCEPTION 'HUMAN_REWARD_CATALOG_PREVIEW_SCOPE_DRIFT';END IF;PERFORM mission_factory_owner.c444_runtime_ports_complete_assert_v1();END $preflight$;
CREATE OR REPLACE FUNCTION public.mission_factory_quest_reward_catalog_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare entries jsonb; human_allowed boolean:=false;
begin
 perform mission_ai_board_owner.staff_only();
 human_allowed:=auth.uid() IS NOT NULL AND auth.role() IS NOT DISTINCT FROM 'authenticated' AND public.is_staff() IS TRUE AND mission_factory_owner.c416_kind_live_v1() IS TRUE AND mission_factory_owner.c444_enabled_v1() IS TRUE AND png_builder_internal.npc_media_completion_staff_v1(auth.uid()) IS TRUE;
 IF human_allowed THEN PERFORM mission_factory_owner.manual_authoring_assert_v1('preview',NULL);END IF;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'label','30 XP per PG · successo/fallimento · 0 Ryō · nessun oggetto',
   'qualified',true,'allowed_content_kinds',jsonb_build_array('quest_ai'),'policy_sha256',p.document_sha256,
   'document',p.document,'scope','staff') order by p.created_at,p.id),'[]'::jsonb) into entries
 from mission_factory_owner.quest_reward_policy_versions p
 where p.qualified and p.scope='staff' and p.document=mission_factory_owner.quest_reward_fixed30_document_v2()
   and p.document_sha256=mission_factory_owner.sha(p.document)
   and exists(select 1 from mission_factory_owner.quest_fixed30_policy_requests q where q.policy_id=p.id and q.document_sha256=p.document_sha256
     and exists(select 1 from mission_factory_owner.catalog_versions c where c.version=q.catalog_version
       and c.document_sha256=q.catalog_sha256 and c.active and c.qualified and c.document_sha256=mission_factory_owner.sha(c.document)))
   and (human_allowed OR exists(select 1 from mission_factory_owner.quest_fixed30_admission where singleton and staff_enabled and qualification_sha256 is not null));
 return jsonb_build_object('schema_version','quest-reward-catalog/2','reward_policies',entries);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.mission_factory_catalog_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c mission_factory_owner.catalog_versions; item jsonb; caps jsonb:='[]'::jsonb;
        maps jsonb:='[]'::jsonb; budgets jsonb:='[]'::jsonb; rewards jsonb:='[]'::jsonb;
        kinds jsonb; active_budget uuid; native_ready boolean; reward_checked jsonb; resources jsonb;
begin
  perform mission_factory_owner.assert_editor(auth.uid());
  select * into c from mission_factory_owner.catalog_versions where active and qualified;
  if not found or mission_factory_owner.sha(c.document)<>c.document_sha256
    then raise exception 'MF_CATALOG_NOT_QUALIFIED' using errcode='55000'; end if;
  kinds:=coalesce(c.document->'content_kinds','[]'::jsonb);
  if jsonb_typeof(kinds)<>'array' then kinds:='[]'::jsonb; end if;
  if not exists(select 1 from jsonb_array_elements(kinds) x where x.value->>'kind'='quest_ai')
    then kinds:=kinds||jsonb_build_array(jsonb_build_object('kind','quest_ai','qualified',false,'reason_code','MF_QUEST_CATALOG_UNQUALIFIED')); end if;
  if jsonb_typeof(c.document->'capabilities')='array' then
    for item in select value from jsonb_array_elements(c.document->'capabilities') loop
      if jsonb_typeof(item)='object' and jsonb_typeof(item->'allowed_content_kinds')='array'
         and item->'allowed_content_kinds' ? 'quest_ai'
         and jsonb_typeof(item->'decision_keys')='array'
         and item->>'family' in('narrative','d100','combat','fato','terminal','reward')
      then caps:=caps||jsonb_build_array(item); end if;
    end loop;
  end if;
  resources:=mission_factory_owner.c352_resource_catalog_v1();
  maps:=resources->'map_references';budgets:=resources->'budget_policies';rewards:=resources->'reward_policies';
  -- Preserve historical resources; the reserved Human view offers only actual fixed30 receipt/catalog-qualified policies.
  IF auth.uid() IS NOT NULL AND auth.role() IS NOT DISTINCT FROM 'authenticated' AND public.is_staff() IS TRUE AND mission_factory_owner.c416_kind_live_v1() IS TRUE AND mission_factory_owner.c444_enabled_v1() IS TRUE AND png_builder_internal.npc_media_completion_staff_v1(auth.uid()) IS TRUE THEN
    PERFORM mission_factory_owner.manual_authoring_assert_v1('preview',NULL);
    SELECT coalesce(jsonb_agg(x.value ORDER BY x.ordinality),'[]'::jsonb) INTO rewards FROM jsonb_array_elements(coalesce(rewards,'[]'::jsonb)) WITH ORDINALITY x(value,ordinality) WHERE x.value#>>'{document,schema_version}' IS DISTINCT FROM 'mission-factory-quest-reward-policy/2';
    rewards:=rewards||(public.mission_factory_quest_reward_catalog_v2()->'reward_policies');
  END IF;
  return jsonb_build_object('schema_version','mission-factory-catalog/2','version',c.version,
    'content_kinds',kinds,'capabilities',caps,'map_references',maps,
    'budget_policies',budgets,'reward_policies',rewards,'limits',coalesce(c.document->'limits','{}'::jsonb)||resources->'limits',
    'quest_compile_qualified',mission_factory_owner.quest_compile_qualified_v2(),
    'quest_compile_reason_code',case when mission_factory_owner.quest_compile_qualified_v2()
      then null else 'MF_QUEST_COMPILE_UNQUALIFIED' end,
    'public_open_qualified',exists(select 1 from mission_factory_owner.quest_fixed30_admission g join mission_public_owner.release_admissions_v1 rel on rel.release_sha256=g.public_release_sha256 where g.singleton and g.public_enabled and rel.public_enabled and g.public_qualification_sha256 is not null),
    'public_open_reason_code',case when exists(select 1 from mission_factory_owner.quest_fixed30_admission g join mission_public_owner.release_admissions_v1 rel on rel.release_sha256=g.public_release_sha256 where g.singleton and g.public_enabled and rel.public_enabled and g.public_qualification_sha256 is not null) then null else 'MF_PUBLIC_OPEN_NOT_QUALIFIED' end);
end $function$
;
